(() => {
  const clean = (s) => ((s || '') + '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const lblOf = (e) => { const p = e.closest('div[class*=form-item]') || e.parentElement; return clean(p && p.innerText).slice(0, 30); };
  const blk = document.getElementById('project');
  return {
    字段: [...document.querySelectorAll('input,textarea,[contenteditable=true]')].filter(vis).map((e, i) => i + ':' + e.tagName + '|ph=' + (e.placeholder || '').slice(0, 24) + '|lbl=' + lblOf(e).slice(0, 22) + '|ka=' + (e.getAttribute('ka') || '')).slice(0, 16),
    按钮: blk ? [...blk.querySelectorAll('[ka]')].map((e) => e.getAttribute('ka') + '|' + clean(e.innerText).slice(0, 8)).filter((t) => /ok|cancel|_del|add/.test(t)).slice(0, 12) : [],
    板块: blk ? clean(blk.innerText).slice(0, 420) : 'NO BLOCK'
  };
})()
